 auto*order=new QHBoxLayout;gl->addLayout(order);for(auto delta:{-1,1})button(order,delta<0?"组上移":"组下移",delta<0?"watchWorkspaceGroupUp":"watchWorkspaceGroupDown",[this,delta]{cleanEditor();applyOperation({{"op","moveGroup"},{"groupId",selected},{"to",groups->currentRow()+delta}});});
