void WatchlistWorkspacePage::attempt(std::function<void()>f){try{need(!property("snapshotLoading").toBool(),"正在读取分组，请稍后；原草稿未改");f();}catch(const std::exception&e){status->setText((uncertain?QString("保存结果未确认；草稿保留，请明确重读。 "):QString{})+QString::fromUtf8(e.what()));}}
QJsonObject WatchlistWorkspacePage::currentGroup()const{auto gs=draft.value("groups").toArray();int at=groupIndex(gs,selected);return at<0?QJsonObject{}:gs[at].toObject();}
void WatchlistWorkspacePage::cleanEditor()const{need(importPreview.isEmpty(),"请先采用或取消导入预览，未覆盖已有编辑");auto g=currentGroup();if(!g.isEmpty())need(name->text()==g.value("name").toString()&&color->text()==g.value("color").toString(),"名称 / 识别色输入尚未确认到草稿，请先确认或取消草稿");}
void WatchlistWorkspacePage::setAsyncReader(std::function<Reader()> factory){readerFactory=std::move(factory);snapshotReader=new PageSnapshotReader(this,{},[this](QJsonObject fresh,QString error){setProperty("snapshotLoading",false);body->setEnabled(true);if(!error.isEmpty()){status->setText("读取失败，原草稿保留："+error);return;}base=draft=fresh;preview={};importPreview={};uncertain=false;mode=0;render();status->setText("分组已载入 · 修改后预览并保存");});reload();}
void WatchlistWorkspacePage::reload(){if(readerFactory){auto work=readerFactory();setProperty("snapshotLoading",true);body->setEnabled(false);status->setText("正在读取分组，可继续切换页面。");snapshotReader->request([work]{return validate(work());});return;}need(bool(read),"宿主尚未提供本机快照");auto fresh=validate(read());base=draft=fresh;preview={};importPreview={};uncertain=false;mode=0;render();status->setText("分组已载入 · 修改后预览并保存");}
void WatchlistWorkspacePage::cancelChanges(){reload();status->setText("草稿已取消；未调用保存。");}
void WatchlistWorkspacePage::applyOperation(QJsonObject op){need(!uncertain,"上次保存结果未确认；请明确重读后再编辑");cleanEditor();auto next=apply(draft,op);transition(base,next);draft=next;preview={};mode=0;if(op.value("op")=="addGroup")selected=op.value("groupId").toString();render();status->setText("变更仅在草稿；删除 / 移出只作用本组，主自选和其它组保留。");}
void WatchlistWorkspacePage::metadata(){need(importPreview.isEmpty(),"请先采用或取消导入预览");need(!uncertain,"保存结果未确认，请重读");auto next=apply(draft,{{"op","renameGroup"},{"groupId",selected},{"name",name->text().trimmed()}});next=apply(next,{{"op","setColor"},{"groupId",selected},{"color",color->text().trimmed()}});transition(base,next);draft=next;preview={};mode=0;render();status->setText("名称 / 识别色已进入草稿；groupId未变化，未保存。");}
void WatchlistWorkspacePage::previewChanges(){need(!uncertain&&bool(read),"保存结果未确认或快照回调未接，请重读");cleanEditor();preview=prepare(base,draft,read());evidence->setPlainText(describe(preview)+QString::fromUtf8(QJsonDocument(preview).toJson(QJsonDocument::Indented)));mode=1;body->setCurrentIndex(mode);status->setText("逐项核对前后成员和顺序；确认提交后由宿主原子保存。");}
void WatchlistWorkspacePage::commitChanges(){need(!uncertain&&!preview.isEmpty()&&bool(read),"需先预览明确变更；未确认结果不得自动重试");cleanEditor();auto now=prepare(base,draft,read());need(equal(now,preview),"预览之后草稿已变，需重新预览");if(now.value("noChange").toBool()){preview={};mode=0;render();status->setText("没有变化；未调用保存。");return;}need(bool(save),"宿主未接原子保存");uncertain=true;auto saved=receipt(base,draft,save(now));base=draft=saved;preview={};uncertain=false;mode=0;render();status->setText("分组已保存；行情与主自选未改。");}
void WatchlistWorkspacePage::rosterChoices(){QString chosen=roster->currentData().toString();roster->clear();roster->addItem("请选择证券","");auto needle=search->text().trimmed();for(auto v:draft.value("instruments").toArray()){auto r=v.toObject();auto label=r.value("name").toString()+" · "+r.value("id").toString().section(':',2,2);if(needle.isEmpty()||label.contains(needle,Qt::CaseInsensitive)||r.value("id").toString().contains(needle,Qt::CaseInsensitive)){roster->addItem(label,r.value("id").toString());roster->setItemData(roster->count()-1,marketHint(r.value("id").toString()),Qt::ToolTipRole);}}roster->setCurrentIndex(std::max(0,roster->findData(chosen)));}
void WatchlistWorkspacePage::render(){filling=true;groups->clear();auto gs=draft.value("groups").toArray();if(groupIndex(gs,selected)<0)selected=gs.isEmpty()?"":gs[0].toObject().value("groupId").toString();for(auto v:gs){auto g=v.toObject();auto*i=new QListWidgetItem(g.value("name").toString()+" · "+QString::number(g.value("memberIds").toArray().size())+"只"+(g.value("readOnly").toBool()?" · 只读":" · 本地"),groups);i->setData(Qt::UserRole,g.value("groupId").toString());i->setToolTip(g.value("groupId").toString());auto c=g.value("color").toString();if(!c.isEmpty())i->setForeground(QColor(c));}groups->setCurrentRow(groupIndex(gs,selected));auto g=currentGroup();name->setText(g.value("name").toString());color->setText(g.value("color").toString());name->setEnabled(!g.isEmpty()&&!g.value("readOnly").toBool());color->setEnabled(name->isEnabled());auto prior=members->currentItem()?members->currentItem()->data(Qt::UserRole).toString():"";members->clear();for(auto v:g.value("memberIds").toArray()){QString label=v.toString();for(auto row:draft.value("instruments").toArray())if(row.toObject()["id"]==v){label=row.toObject()["name"].toString()+"  "+v.toString().section(':',2,2);break;}auto*i=new QListWidgetItem(label,members);i->setData(Qt::UserRole,v.toString());i->setToolTip(marketHint(v.toString()));if(v.toString()==prior)members->setCurrentItem(i);}rosterChoices();body->setCurrentIndex(mode);filling=false;}
QJsonObject WatchlistWorkspacePage::saveState()const{if(base.isEmpty())return {};return {{"schema","watchlist-workspace-view/v1"},{"base",management(base)},{"draftGroups",draft.value("groups")},{"selectedGroupId",selected},{"memberId",members->currentItem()?members->currentItem()->data(Qt::UserRole).toString():""},{"nameInput",name->text()},{"colorInput",color->text()},{"newNameInput",newName->text()},{"search",search->text()},{"uncertain",uncertain}};}
void WatchlistWorkspacePage::restoreState(QJsonObject state){if(state.isEmpty())return;if(snapshotReader)snapshotReader->cancel();setProperty("snapshotLoading",false);body->setEnabled(true);need(text(state,"schema")=="watchlist-workspace-view/v1"&&state.value("base").isObject()&&state.value("draftGroups").isArray()&&state.value("uncertain").isBool(),"分组草稿状态损坏，未采用");auto b=validate(state.value("base").toObject()),d=b;d["groups"]=state.value("draftGroups");transition(b,d);if(read&&!readerFactory){auto fresh=validate(read());if(fresh.value("revision")==b.value("revision")&&fingerprint(fresh)==fingerprint(b)){b=fresh;d=b;d["groups"]=state.value("draftGroups");}}base=b;draft=d;importPreview={};selected=text(state,"selectedGroupId");uncertain=state.value("uncertain").toBool();preview={};mode=0;render();name->setText(text(state,"nameInput"));color->setText(text(state,"colorInput"));newName->setText(text(state,"newNameInput"));search->setText(text(state,"search"));auto member=text(state,"memberId");for(int i=0;i<members->count();i++)if(members->item(i)->data(Qt::UserRole).toString()==member)members->setCurrentRow(i);status->setText("未保存草稿已恢复；需重新预览，版本变化将拒绝提交。");}
bool WatchlistWorkspacePage::back(){if(!importPreview.isEmpty()){cancelBackupImport();return true;}if(mode){mode=0;body->setCurrentIndex(0);return true;}auto g=currentGroup();bool input=!g.isEmpty()&&(name->text()!=g.value("name").toString()||color->text()!=g.value("color").toString());if(uncertain||input||!equal(base.value("groups"),draft.value("groups"))){status->setText("存在未保存草稿或未确认保存结果；请明确取消 / 重读或提交后离开。");return true;}return false;}
void WatchlistWorkspacePage::setDarkTheme(bool dark){setStyleSheet(QString("QWidget{background:%1;color:%2;} QLineEdit,QPlainTextEdit,QListWidget,QComboBox{background:%3;} QPushButton{padding:5px;min-height:24px;} QListWidget::item:selected{background:%4;}").arg(dark?"#111a26":"#ffffff",dark?"#dce5f0":"#243449",dark?"#172232":"#f4f7fb",dark?"#203955":"#e4effc"));}


void WatchlistWorkspacePage::setBackupActions(std::function<void()> e,std::function<void()> i){backupExportRequest=std::move(e);backupImportRequest=std::move(i);}
void WatchlistWorkspacePage::cleanImportTarget()const{need(!uncertain&&!base.isEmpty()&&equal(base.value("groups"),draft.value("groups")),"已有未保存草稿或保存结果未确认；导入未替换，请先明确处理");auto g=currentGroup();need((g.isEmpty()||(name->text()==g.value("name").toString()&&color->text()==g.value("color").toString()))&&newName->text().isEmpty(),"已有未确认名称/颜色/新组输入；导入未覆盖");}
QByteArray WatchlistWorkspacePage::exportBackupBytes()const{need(!uncertain&&bool(read),"保存结果未确认或宿主未接快照；未导出");return watchlistBackup::encodeBackup(watchlistBackup::exportBackup(read()));}
void WatchlistWorkspacePage::previewBackupImport(QByteArray bytes){need(importPreview.isEmpty(),"已有导入预览，请先采用或取消");cleanImportTarget();need(bool(read),"宿主未接当前快照");auto candidate=watchlistBackup::previewImport(watchlistBackup::decodeBackup(bytes),base,read());importPreview=candidate;preview={};auto change=candidate.value("change").toObject();evidence->setPlainText("分组备份差异预览 · 8 MiB上限\n采用后仅进入草稿；仍需预览变更并确认提交。\n"+describe(change)+QString::fromUtf8(QJsonDocument(candidate).toJson(QJsonDocument::Indented)));mode=1;body->setCurrentIndex(mode);status->setText("备份已校验；只读来源组与当前一致。尚未改变草稿或保存。");}
void WatchlistWorkspacePage::acceptBackupImport(){need(!importPreview.isEmpty()&&bool(read),"需先选择备份并预览");cleanImportTarget();auto next=watchlistBackup::importDraft(base,importPreview,read());draft=next;importPreview={};preview={};mode=0;evidence->clear();render();status->setText("完整分组配置已进入草稿；请预览变更后确认提交。主自选行情未改。");}
void WatchlistWorkspacePage::cancelBackupImport(){if(importPreview.isEmpty())return;importPreview={};mode=0;evidence->clear();body->setCurrentIndex(0);status->setText("导入预览已取消；原草稿/输入保留，未调用保存。");}
